import "core-js/modules/es.array.push.js";
export default {
  name: "UnitItemsDialog",
  props: {
    ItemDialog: Boolean,
    items: {
      type: Array,
      default: () => []
    },
    loading: Boolean
  },
  emits: ["close"],
  data() {
    return {
      headers: [{
        title: "ITEM",
        value: "item_name"
      }, {
        title: "STOCK",
        value: "stock_quantity",
        align: "center"
      }, {
        title: "SALE PRICE",
        value: "sale_price",
        align: "center"
      }, {
        title: "PURCHASE PRICE",
        value: "purchase_price",
        align: "center"
      }, {
        title: "STOCK VALUE",
        value: "stock_value",
        align: "center"
      }, {
        title: "STATUS",
        value: "item_status",
        align: "center"
      }],
      currentPage: 1,
      itemsPerPage: 10
    };
  },
  computed: {
    totalItems() {
      return this.items.length;
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    paginatedProducts() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.items.slice(start, end);
    },
    visiblePages() {
      const pages = [];
      for (let i = 1; i <= this.pageCount; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  mounted() {
    this.windowHeight = window.innerHeight - 250;
  },
  methods: {
    getStockColor(qty) {
      const val = Number(qty) || 0;
      if (val <= 0) return "red";
      if (val < 10) return "green-lighten-2";
      return "green";
    }
  }
};
